package com.servicedesk360.service;
import com.servicedesk360.dto.dashboard.*; import com.servicedesk360.entity.*; import com.servicedesk360.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service public class DashboardService{private final TicketRepository tickets;private final TaskRepository tasks;private final UserRepository users;private final CurrentUserService current;public DashboardService(TicketRepository t,TaskRepository ta,UserRepository u,CurrentUserService c){tickets=t;tasks=ta;users=u;current=c;} @Transactional(readOnly=true) public DashboardSummary summary(){var me=current.getRequiredUser();Long t=me.tenantId();Long userId=me.user().getId();var activeTickets=List.of(TicketStatus.OPEN,TicketStatus.IN_PROGRESS,TicketStatus.WAITING_FOR_REQUESTER);var activeTasks=List.of(TaskStatus.TODO,TaskStatus.IN_PROGRESS,TaskStatus.BLOCKED);long tenantOpenTickets=tickets.countByTenantIdAndStatus(t,TicketStatus.OPEN);long tenantInProgress=tickets.countByTenantIdAndStatus(t,TicketStatus.IN_PROGRESS);long tenantResolved=tickets.countByTenantIdAndStatus(t,TicketStatus.RESOLVED);long tenantOpenTasks=tasks.countByTenantIdAndStatus(t,TaskStatus.TODO)+tasks.countByTenantIdAndStatus(t,TaskStatus.IN_PROGRESS)+tasks.countByTenantIdAndStatus(t,TaskStatus.BLOCKED);long tenantDoneTasks=tasks.countByTenantIdAndStatus(t,TaskStatus.DONE);long myOpenTickets=me.role()==Role.REQUESTER?tickets.countByTenantIdAndRequesterIdAndStatusIn(t,userId,activeTickets):tickets.countByTenantIdAndAssigneeIdAndStatusIn(t,userId,activeTickets);long myOpenTasks=tasks.countByTenantIdAndAssigneeIdAndStatusIn(t,userId,activeTasks);if(me.role()==Role.REQUESTER||me.role()==Role.AGENT)return new DashboardSummary(me.role().name(),myOpenTickets,0,0,myOpenTasks,0,0,myOpenTickets,myOpenTasks);return new DashboardSummary(me.role().name(),tenantOpenTickets,tenantInProgress,tenantResolved,tenantOpenTasks,tenantDoneTasks,users.countByTenantId(t),myOpenTickets,myOpenTasks);}}
